def _flatten_schema(raw: Dict[str, Any], prefix: str = "") -> Dict[str, Dict[str, Any]]:
    """Flatten the nested TOML schema into {dotpath: {type, default, ...}}."""
    result: Dict[str, Dict[str, Any]] = {}
    schema_fields = {"type", "default", "constraint_class", "min_layer", "description", "allowed_values"}
    required_fields = {"type", "default", "constraint_class", "min_layer", "description"}

    for key, value in raw.items():
        full_key = f"{prefix}.{key}" if prefix else key
        if not isinstance(value, dict):
            raise ValueError(f"{full_key}: schema node must be a table, got {type(value).__name__}")

        node_fields = set(value.keys())
        if "type" in value:
            missing = required_fields - node_fields
            extra = node_fields - schema_fields
            if missing:
                raise ValueError(f"{full_key}: missing required schema fields: {sorted(missing)}")
            if extra:
                raise ValueError(f"{full_key}: unknown schema fields: {sorted(extra)}")
            result[full_key] = value
        else:
            if node_fields & schema_fields:
                raise ValueError(f"{full_key}: malformed parameter definition (missing 'type')")
            result.update(_flatten_schema(value, full_key))
    return result
